<dialog id="profileVisibilityDialog" class="profile-visibility-dialog" aria-labelledby="profileVisibilityTitle" data-load-url="{{ route('system.scope.options') }}" data-save-url="{{ route('system.scope') }}">
  <form id="profileVisibilityForm" method="dialog">
    <header class="profile-visibility-dialog-header"><span class="profile-visibility-dialog-icon"><i class="bi bi-globe2" aria-hidden="true"></i></span><div><span class="profile-visibility-kicker">ADMINISTRATOR SETTINGS</span><h2 id="profileVisibilityTitle">Choose your data visibility</h2></div><button id="closeProfileVisibility" class="profile-visibility-close" type="button" aria-label="Close visibility settings"><i class="bi bi-x-lg" aria-hidden="true"></i></button></header>
    <p class="profile-visibility-intro">Select regions and offices to limit records shown in TMIS. Offices follow the selected regions. Clear a list to show all available records for that level.</p>
    <div class="profile-visibility-grid">
      <fieldset class="profile-visibility-list"><div class="profile-visibility-list-heading"><div><legend><i class="bi bi-map" aria-hidden="true"></i> Regions <span id="profileVisibilityRegionCount"></span></legend><small>Choose one or more regions</small></div><div class="profile-visibility-actions"><button type="button" data-visibility-select="regions">Select all</button><button type="button" data-visibility-clear="regions">Clear</button></div></div><label class="visually-hidden" for="profileVisibilityRegionSearch">Search regions</label><div class="profile-visibility-search"><i class="bi bi-search" aria-hidden="true"></i><input id="profileVisibilityRegionSearch" type="search" placeholder="Search regions"></div><div class="profile-visibility-options" id="profileVisibilityRegions"><p class="profile-visibility-loading">Loading regions…</p></div></fieldset>
      <fieldset class="profile-visibility-list"><div class="profile-visibility-list-heading"><div><legend><i class="bi bi-building" aria-hidden="true"></i> Offices <span id="profileVisibilityOfficeCount"></span></legend><small id="profileVisibilityOfficeScope">Select regions to narrow the office list</small></div><div class="profile-visibility-actions"><button type="button" data-visibility-select="offices">Select all</button><button type="button" id="refreshProfileVisibilityOffices"><i class="bi bi-arrow-clockwise" aria-hidden="true"></i> Refresh</button><button type="button" data-visibility-clear="offices">Clear</button></div></div><label class="visually-hidden" for="profileVisibilityOfficeSearch">Search offices</label><div class="profile-visibility-search"><i class="bi bi-search" aria-hidden="true"></i><input id="profileVisibilityOfficeSearch" type="search" placeholder="Search offices"></div><div class="profile-visibility-options" id="profileVisibilityOffices"><p class="profile-visibility-loading">Loading offices…</p></div></fieldset>
    </div>
    <div id="profileVisibilityError" class="profile-visibility-error" role="alert" hidden></div>
    <footer class="profile-visibility-dialog-footer"><span><i class="bi bi-info-circle" aria-hidden="true"></i> Saved settings also apply in System Settings &gt; Data visibility.</span><button id="cancelProfileVisibility" type="button" class="btn self-secondary">Cancel</button><button id="saveProfileVisibility" type="submit" class="btn btn-success"><i class="bi bi-check2" aria-hidden="true"></i> Save visibility</button></footer>
  </form>
</dialog>
